def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    colors = {5: 8, 7: 4, 9: 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 2 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            n = r1-r0+1
            if n not in colors or c1-c0+1 != n:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if border.issubset(set(comp)):
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if out[y][x] == 0:
                            out[y][x] = colors[n]
    return out
